{
  "case_id": "C01",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook",
      "narration": "You have heard that how long you sleep matters. This study asked a different question: does it matter whether you sleep at the same times each night?",
      "on_screen": "Title card: How long you sleep, versus when. Two calendar strips, one with matching sleep blocks, one scattered.",
      "claim_refs": ["SYN-C01:Background"]
    },
    {
      "beat": "What they did",
      "narration": "Researchers followed just over forty-one thousand adults aged forty to sixty-nine. Each wore a wrist tracker for one week, and got a sleep regularity score from zero to one hundred.",
      "on_screen": "Wrist accelerometer icon; 41,208 adults, ages 40 to 69; 7 nights; score dial from 0 to 100.",
      "claim_refs": ["SYN-C01:Abstract", "SYN-C01:Methods"]
    },
    {
      "beat": "What they found",
      "narration": "Over about six years, one thousand eight hundred and seventy-three people had a first heart or metabolic event. The least regular fifth had a thirty-four percent higher rate than the most regular fifth, even after accounting for age, weight, smoking, shift work and average sleep length. And the risk climbed step by step across the groups.",
      "on_screen": "Bar chart of the five quintiles rising from 1.00 to 1.34, with confidence bars; adjustment factors listed beneath.",
      "claim_refs": ["SYN-C01:Abstract", "SYN-C01:Results"]
    },
    {
      "beat": "What it does not show",
      "narration": "But this is an observational study. Sleep was measured only once, over a single week, so it cannot show that irregular sleep causes disease. Something else about irregular sleepers could explain the link.",
      "on_screen": "Caution panel: observed, not tested. One 7-day snapshot; no repeat measurement; association is not causation.",
      "claim_refs": ["SYN-C01:Study design", "SYN-C01:Limitations"]
    },
    {
      "beat": "Takeaway",
      "narration": "So the honest summary is this: sleep timing looks like a promising target, and the next step is a trial that actually asks people to steady their schedules.",
      "on_screen": "Closing card: A lead worth testing. Next step: randomised trial of sleep-timing stabilisation.",
      "claim_refs": ["SYN-C01:Conclusion", "SYN-C01:Discussion"]
    }
  ]
}
